2	import { requireUser } from "@/lib/auth";
3	import { EmptyState } from "@/components/ui/primitives";
4	import type { CalendarInfo, CalEvent, TaskItem } from "@/lib/calendar/types";
5	import { listCalendars, listEvents, listTasks } from "@/lib/actions-calendar";
6	import { CalendarClient } from "@/components/customer/calendar/CalendarClient";
7	
8	export const dynamic = "force-dynamic";
9	
10	export const metadata = { title: "Calendar — Nxeon" };
11	
12	/** Local-time first/last day of the current month grid (6 weeks), so the
13	 *  initial fetch matches the Month view the client opens on. */
14	function initialRange(): [string, string] {
15	  const now = new Date();
16	  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
17	  const gridStart = new Date(firstOfMonth);
18	  gridStart.setDate(gridStart.getDate() - gridStart.getDay());
19	  const gridEnd = new Date(gridStart);
20	  gridEnd.setDate(gridEnd.getDate() + 42);
21	  return [gridStart.toISOString(), gridEnd.toISOString()];
22	}
23	
24	export default async function CalendarPage() {
25	  await requireUser();
26	
27	  let calendars: CalendarInfo[] = [];
28	  let events: CalEvent[] = [];
29	  let tasks: TaskItem[] = [];
30	  let failed = false;
31	
32	  try {
33	    calendars = await listCalendars();
34	    if (calendars.length > 0) {
35	      const [start, end] = initialRange();
36	      [events, tasks] = await Promise.all([listEvents(start, end), listTasks()]);
37	    }
38	  } catch {
39	    failed = true;
40	  }
41	
42	  if (failed || calendars.length === 0) {
43	    return (
44	      <div className="mx-auto max-w-2xl pt-10">
45	        <EmptyState
46	          title="No calendar connected"
47	          sub="Your calendar lives alongside your Nxeon mailbox. Set up business email on one of your domains to start scheduling events and tracking tasks here."
48	          action={
49	            <Link href="/dashboard/email" className="btn-primary">
50	              Set up email
51	            </Link>
52	          }
53	        />
54	      </div>
55	    );
56	  }
57	
58	  return (
59	    <CalendarClient initialCalendars={calendars} initialEvents={events} initialTasks={tasks} />
60	  );
61	}
