139	function OrderPanel({
140	  suggestedDomains,
141	  plans,
142	  balanceCents,
143	}: {
144	  suggestedDomains: string[];
145	  plans: PlanOpt[];
146	  balanceCents: number;
147	}) {
148	  const [domain, setDomain] = useState(suggestedDomains[0] ?? "");
149	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
150	  const [error, setError] = useState<string | null>(null);
151	  const [ok, setOk] = useState(false);
152	  const [pending, start] = useTransition();
153	
154	  const selected = plans.find((p) => p.id === planId);
155	  const registered = new Set(suggestedDomains.map((d) => d.toLowerCase()));
156	  const trimmed = domain.trim().toLowerCase();
157	  const isExternal = trimmed.length > 0 && !registered.has(trimmed);
158	
159	  function submit() {
160	    if (!domain.trim()) {
161	      setError("Enter a domain.");
162	      return;
163	    }
164	    setError(null);
165	    setOk(false);
166	    start(async () => {
167	      const res = await orderEmailHosting(domain.trim(), planId);
168	      if (res?.error) setError(res.error);
