210	            </p>
211	          </div>
212	          <div>
213	            <label className="label">Plan</label>
214	            <select className="input" value={planId} onChange={(e) => setPlanId(e.target.value)}>
215	              {plans.map((p) => (
216	                <option key={p.id} value={p.id}>
217	                  {p.name} — {p.mailboxes} mailbox{p.mailboxes === 1 ? "" : "es"} · {p.storageGB}GB ·{" "}
218	                  {fmtMoney(p.priceCents)}
219	                  {p.termMonths > 1 ? `/${p.termMonths}mo` : "/mo"}
