221	              ))}
222	            </select>
223	          </div>
224	        </div>
225	
226	        {selected && (
227	          <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/[0.06] px-3 py-2 text-sm">
228	            <span className="text-slate-300">
229	              {selected.mailboxes} mailbox{selected.mailboxes === 1 ? "" : "es"} · {selected.storageGB} GB each
230	            </span>
231	            <span className="text-white">
232	              {fmtMoney(selected.priceCents)}
233	              {selected.termMonths > 1 ? ` / ${selected.termMonths} mo` : " / mo"}
