235	          </div>
236	        )}
237	
238	        <div className="flex flex-wrap items-center justify-between gap-3">
239	          <span className="text-xs text-slate-500">
240	            Wallet balance: <span className="text-slate-300">{fmtMoney(balanceCents)}</span>
