311	/** Small copy-to-clipboard button (mailbox password reveal/reset). */
312	function CopyChip({ text }: { text: string }) {
313	  const [copied, setCopied] = useState(false);
314	  return (
315	    <button
316	      type="button"
317	      className="btn-secondary shrink-0 px-2 py-1 text-xs"
318	      onClick={async () => {
319	        try {
320	          await navigator.clipboard.writeText(text);
321	          setCopied(true);
322	          setTimeout(() => setCopied(false), 1500);
323	        } catch {
324	          /* clipboard blocked — no-op */
325	        }
326	      }}
327	    >
328	      {copied ? "Copied" : "Copy"}
329	    </button>
330	  );
331	}
332	
333	/**
334	 * Badge for a mailbox's REAL status.
335	 *
336	 * Every row used to render a literal `<Badge tone="amber">Provisioning</Badge>`
337	 * while the column moved through ACTIVE / FAILED / SUSPENDED underneath. When
338	 * Mailcow was down at creation time `provisionMailboxOnMailcow` set FAILED and
339	 * `addMailbox` still returned ok, so the row read "Provisioning" forever and
340	 * mail to that address bounced with nothing on screen suggesting a problem.
341	 */
342	function statusBadge(status: string): { tone: "green" | "amber" | "red" | "slate"; label: string } {
343	  switch (status) {
344	    case "ACTIVE":
345	      return { tone: "green", label: "Active" };
346	    case "FAILED":
347	      return { tone: "red", label: "Setup failed" };
348	    case "SUSPENDED":
349	      return { tone: "slate", label: "Suspended" };
350	    case "PROVISIONING":
351	      return { tone: "amber", label: "Provisioning" };
352	    default:
353	      // Never invent a friendly label for a value we don't know — show it raw so
354	      // an unmapped state is visible rather than silently rendered as healthy.
355	      return { tone: "slate", label: status || "Unknown" };
356	  }
357	}
358	
359	function MailboxItem({ mailbox }: { mailbox: MailboxRow }) {
360	  const [pending, start] = useTransition();
361	  const [pwPending, startPw] = useTransition();
362	  const [retryPending, startRetry] = useTransition();
363	  const [error, setError] = useState<string | null>(null);
364	  // A success-with-a-caveat, distinct from an error: e.g. removed from the account
365	  // while the mail server was unreachable, so the mailbox itself may still exist.
