536	const CHECK_TONE: Record<CheckStatus, "green" | "amber" | "red" | "slate"> = {
537	  pass: "green",
538	  warn: "amber",
539	  fail: "red",
540	  unknown: "slate",
541	};
542	
543	const CHECK_LABEL: Record<CheckStatus, string> = {
544	  pass: "Pass",
545	  warn: "Warning",
546	  fail: "Fail",
547	  unknown: "Unknown",
548	};
