550	/**
551	 * Per-domain SPF / DKIM / DMARC / MX self-check.
552	 *
553	 * WHY: "my mail goes to spam" was undiagnosable from inside the product. The
554	 * platform owner hit exactly this and had to diagnose it with an external
555	 * third-party tool, so every customer in the same position had no route at all.
556	 *
557	 * Two things this panel must never do, because both would make it the codebase's
558	 * recurring defect in a new place — a surface reporting an outcome it never
559	 * verified, here telling someone their mail is fine while it goes to spam:
560	 *
561	 *   1. Report a status the server did not derive from DNS. Every badge below
562	 *      comes from `checkEmailDeliverability`, which reads the zone's own
563	 *      AUTHORITATIVE nameservers (this host's `hosts: files myhostname dns`
564	 *      nsswitch order can answer a lookup out of /etc/hosts while looking like a
565	 *      real query — that produced one confidently wrong diagnosis already).
566	 *   2. Round a partial answer up. `unknown` renders as its own slate state, not
567	 *      as a pass, and the nameservers actually queried are printed so the result
568	 *      is auditable rather than taken on trust.
569	 *
570	 * Not auto-run: each check is several outbound DNS queries plus one Mailcow call,
571	 * and the customer has to be looking at it for the answer to be useful.
572	 */
573	function DeliverabilityPanel({
574	  subscriptionId,
575	  domainName,
576	}: {
577	  subscriptionId: string;
578	  domainName: string;
579	}) {
580	  const [report, setReport] = useState<DeliverabilityReport | null>(null);
581	  const [error, setError] = useState<string | null>(null);
582	  const [pending, start] = useTransition();
583	
584	  function run() {
585	    setError(null);
586	    start(async () => {
587	      const res = await checkEmailDeliverability(subscriptionId);
588	      if (res?.error) {
589	        setError(res.error);
590	        setReport(null);
591	      } else if (res?.report) {
592	        setReport(res.report);
593	      }
594	    });
595	  }
596	
597	  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
598	  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
599	  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;
600	
601	  return (
602	    <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
603	      <div className="flex flex-wrap items-center justify-between gap-2">
604	        <div className="flex flex-wrap items-center gap-2">
605	          <span className="text-sm font-semibold text-white">Deliverability check</span>
606	          {report &&
607	            (failing > 0 ? (
608	              <Badge tone="red">
609	                {failing} problem{failing === 1 ? "" : "s"}
610	              </Badge>
611	            ) : unknown > 0 ? (
612	              <Badge tone="slate">Incomplete</Badge>
613	            ) : warning > 0 ? (
614	              <Badge tone="amber">
615	                {warning} warning{warning === 1 ? "" : "s"}
616	              </Badge>
617	            ) : (
618	              <Badge tone="green">All checks pass</Badge>
619	            ))}
620	        </div>
621	        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
622	          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
623	        </button>
624	      </div>
625	
626	      <p className="mt-2 text-xs text-slate-400">
627	        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
628	        and DMARC. If your mail is landing in spam, a failing row here is usually why.
629	      </p>
630	
631	      {error && (
632	        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
633	          {error}
634	        </div>
635	      )}
636	
637	      {report && (
638	        <div className="mt-3 space-y-2">
639	          {report.error && (
640	            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
641	              {report.error}
642	            </div>
643	          )}
644	
645	          {report.checks.map((c) => (
646	            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
647	              <div className="flex flex-wrap items-center gap-2">
648	                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
649	                <span className="text-sm font-medium text-slate-200">{c.label}</span>
650	                <span className="text-[11px] text-slate-500">
651	                  {c.type} · <span className="font-mono">{c.host}</span>
652	                </span>
653	              </div>
654	
655	              <div className="mt-2 grid gap-2 sm:grid-cols-2">
656	                <div className="min-w-0">
657	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
658	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
659	                    {c.observed || "— nothing published —"}
660	                  </code>
661	                </div>
662	                <div className="min-w-0">
663	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
664	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
665	                    {c.expected || "—"}
666	                  </code>
667	                </div>
668	              </div>
669	
670	              <p
671	                className={`mt-2 text-xs ${
672	                  c.status === "fail"
673	                    ? "text-red-400"
674	                    : c.status === "warn"
675	                      ? "text-amber-400"
676	                      : c.status === "pass"
677	                        ? "text-emerald-300/80"
678	                        : "text-slate-400"
679	                }`}
680	              >
681	                {c.detail}
682	              </p>
683	            </div>
684	          ))}
685	
686	          {/* Printing the nameservers is the point, not decoration: it is how the
687	              customer (or support) can tell this answer came from the zone's own
688	              authority and not from a stale recursive cache. */}
689	          <p className="text-[11px] text-slate-500">
690	            {report.nameservers.length > 0 ? (
691	              <>
692	                Read directly from this domain&apos;s nameservers (
693	                <span className="font-mono">{report.nameservers.join(", ")}</span>), so a record you
694	                just changed shows up straight away.
695	              </>
696	            ) : (
697	              <>Couldn&apos;t reach this domain&apos;s nameservers, so no record could be read.</>
698	            )}{" "}
699	            Checked {new Date(report.checkedAt).toLocaleTimeString()}.
700	          </p>
701	        </div>
702	      )}
703	    </div>
704	  );
705	}
