230	          }. Now hit Verify DNS below (allow a minute for propagation).`,
231	        );
232	      }
233	    });
234	  }
235	
236	  return (
237	    <div className="mt-3 rounded-lg border border-sky-500/30 bg-sky-500/[0.06] p-3">
238	      <div className="flex flex-wrap items-center gap-2">
