23	// Attachment limits — mirrored server-side (the server re-validates and is the
24	// source of truth). Kept here only for fast, friendly client-side feedback.
25	const MAX_ATTACHMENTS = 10;
26	const MAX_ATTACHMENTS_TOTAL_BYTES = 20 * 1024 * 1024; // 20 MB
27	
28	// A file the user has attached, already read into base64 in the browser.
29	type Attachment = {
30	  id: string;
31	  filename: string;
32	  contentType: string;
33	  size: number; // decoded byte size
