37	function formatBytes(bytes: number): string {
38	  if (bytes < 1024) return `${bytes} B`;
39	  const kb = bytes / 1024;
40	  if (kb < 1024) return `${kb < 10 ? kb.toFixed(1) : Math.round(kb)} KB`;
41	  const mb = kb / 1024;
42	  return `${mb < 10 ? mb.toFixed(1) : Math.round(mb)} MB`;
43	}
44	
45	// Read a File into raw base64 (stripping the "data:*;base64," prefix).
46	function readFileBase64(file: File): Promise<string> {
47	  return new Promise((resolve, reject) => {
48	    const reader = new FileReader();
49	    reader.onerror = () => reject(new Error(`Could not read ${file.name}.`));
50	    reader.onload = () => {
51	      const result = String(reader.result || "");
52	      const comma = result.indexOf(",");
53	      resolve(comma >= 0 ? result.slice(comma + 1) : result);
54	    };
55	    reader.readAsDataURL(file);
56	  });
57	}
