279	/** Escape a value for safe interpolation into a double-quoted HTML attribute. */
280	function escAttr(v: string): string {
281	  return v
282	    .replace(/&/g, "&amp;")
283	    .replace(/"/g, "&quot;")
284	    .replace(/</g, "&lt;")
285	    .replace(/>/g, "&gt;");
286	}
287	
288	/** Clamp a signature-image width to a sane px range so it never breaks the email layout. */
289	function clampImgWidth(n: number): number {
290	  return Math.min(1000, Math.max(40, Math.round(n)));
291	}
292	
293	/** Escape plain text into HTML for the legacy-plain -> HTML seeding path. */
294	function plainToHtml(plain: string): string {
295	  const esc = plain.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
296	  return `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;color:#334155">${esc.replace(/\n/g, "<br>")}</div>`;
297	}
