326	  // --- Image resize: click-to-select + a size control (presets + slider/number). ---
327	  // The active image is only tracked in state + tagged with an editor-only class for
328	  // the selection ring; that class is stripped before the HTML is ever read for save.
329	  const [activeImg, setActiveImg] = useState<HTMLImageElement | null>(null);
330	  const [imgWidth, setImgWidth] = useState(320);
331	  const [imgFull, setImgFull] = useState(false);
332	
333	  // Seed the contentEditable once (React never re-writes it, so the caret is safe).
334	  useEffect(() => {
