336	    // eslint-disable-next-line react-hooks/exhaustive-deps
337	  }, []);
338	
339	  // Read the editor HTML with editor-only artifacts (the image selection ring class)
340	  // stripped, so the stored signature never carries a selection outline or empty class.
341	  const getCleanHtml = useCallback(() => {
342	    const el = editorRef.current;
343	    if (!el) return "";
344	    const clone = el.cloneNode(true) as HTMLElement;
345	    clone.querySelectorAll("img").forEach((im) => {
346	      im.classList.remove("nx-img-active");
347	      if (!im.getAttribute("class")) im.removeAttribute("class");
348	    });
349	    return clone.innerHTML;
350	  }, []);
351	
352	  const sync = useCallback(() => setHtml(getCleanHtml()), [getCleanHtml]);
353	
354	  // Highlight an image as the active one (adds the editor-only ring class) and
355	  // initialise the size control from its current inline width.
356	  const selectImg = useCallback((img: HTMLImageElement) => {
357	    const el = editorRef.current;
358	    if (el) el.querySelectorAll("img.nx-img-active").forEach((i) => i.classList.remove("nx-img-active"));
359	    img.classList.add("nx-img-active");
360	    const sw = img.style.width.trim();
361	    const full = sw === "100%";
362	    let w = 0;
363	    if (sw.endsWith("px")) w = parseInt(sw, 10);
364	    if (!w) w = Math.round(img.getBoundingClientRect().width) || img.naturalWidth || 320;
365	    setActiveImg(img);
366	    setImgFull(full);
367	    setImgWidth(clampImgWidth(w));
368	  }, []);
369	
370	  const deselectImg = useCallback(() => {
371	    const el = editorRef.current;
372	    if (el)
373	      el.querySelectorAll("img.nx-img-active").forEach((i) => {
374	        i.classList.remove("nx-img-active");
375	        if (!i.getAttribute("class")) i.removeAttribute("class");
376	      });
377	    setActiveImg(null);
378	  }, []);
379	
380	  // Apply a fixed pixel width, keeping max-width:100% + height:auto so it never
381	  // overflows the email or distorts. Updates live as the slider moves.
382	  const applyImgWidth = useCallback(
383	    (px: number) => {
384	      const img = activeImg;
