841	/* -------------------------------------------------------------------------- */
842	/* Live rule status (auto-reply + forwarding)                                  */
843	/* -------------------------------------------------------------------------- */
844	
845	/**
846	 * Read back what the MAIL SERVER is actually running for this mailbox.
847	 *
848	 * WHY this exists: both of these sections used to carry a hardcoded amber
849	 * "…is rolling out — until then these settings are stored but not sent"
850	 * notice. Auto-reply and forwarding really were store-only then; they are real
851	 * sieve now, so that fixed sentence had become a lie in the other direction —
852	 * telling a customer their working out-of-office does nothing. Neither the old
853	 * notice nor a hardcoded "Active ✓" would be honest, because neither asked the
854	 * server. This does ask, and reports the answer.
855	 *
856	 * `bump` is incremented after every successful save so the band re-reads the
857	 * live script rather than assuming the save took effect.
858	 */
859	function useRuleStatus(mailboxAddress: string | undefined, bump: number) {
860	  const [status, setStatus] = useState<MailRuleStatus | null>(null);
861	  const [loading, setLoading] = useState(true);
862	
863	  useEffect(() => {
864	    let alive = true;
865	    setLoading(true);
866	    getMailRuleStatus(mailboxAddress)
867	      .then((s) => alive && setStatus(s))
868	      .catch(
869	        () =>
870	          alive &&
871	          // A thrown action (network/auth) must not render as "not active" —
872	          // that would be the same unverified claim in miniature.
873	          setStatus({
874	            supported: false,
875	            autoReplyLive: false,
876	            forwardingLive: false,
877	            error: "Couldn't reach the mail server to check this rule.",
878	          }),
879	      )
880	      .finally(() => alive && setLoading(false));
881	    return () => {
882	      alive = false;
883	    };
884	  }, [mailboxAddress, bump]);
885	
886	  return { status, loading };
887	}
