889	/**
890	 * State of one rule on the mail server, compared against what is saved here.
891	 *
892	 * The disagreement case (`savedOn && !live`) is the one worth surfacing loudly:
893	 * it is the only signal a customer gets that the push to the mail server did not
894	 * take, and it is the exact failure the old "Saved." toast used to hide.
895	 */
896	function RuleStatusNote({
897	  status,
898	  loading,
