916	  }
917	
918	  if (!status.supported) {
919	    return (
920	      <div className={`${base} border-amber-400/20 bg-amber-400/[0.06] text-amber-200/90`}>
921	        This rule is <span className="font-medium">not being applied on the mail server</span>.{" "}
922	        {status.error ?? "Mail rules are unavailable for this mailbox right now."}
