1416	function PasswordSection({ mailboxAddress }: { mailboxAddress?: string }) {
1417	  const [busy, setBusy] = useState(false);
1418	  const [password, setPassword] = useState<string | null>(null);
1419	  const [err, setErr] = useState<string | null>(null);
1420	
1421	  async function reset() {
1422	    if (!confirm("Reset this mailbox's password? The current password will stop working everywhere.")) return;
1423	    setBusy(true);
1424	    setErr(null);
1425	    setPassword(null);
1426	    try {
1427	      const res = await resetPassword(mailboxAddress);
1428	      if (res.error) setErr(res.error);
1429	      else if (res.password) setPassword(res.password);
1430	    } catch (e) {
1431	      setErr(e instanceof Error ? e.message : "Couldn't reset the password.");
1432	    } finally {
1433	      setBusy(false);
1434	    }
1435	  }
1436	
1437	  return (
1438	    <div className="space-y-5">
1439	      <SectionHead
1440	        title="Change password"
1441	        sub="Generate a new password for this mailbox. It applies to webmail and any connected mail apps."
1442	      />
1443	
1444	      {password ? (
1445	        <div className="space-y-3">
1446	          <div className="rounded-xl border border-emerald-400/20 bg-emerald-400/[0.06] px-4 py-3 text-xs text-emerald-200/90">
1447	            New password set. Copy it now — it won't be shown again.
1448	          </div>
1449	          <CopyField label="New password" value={password} mono />
1450	        </div>
1451	      ) : (
1452	        <p className="text-sm text-slate-400">
1453	          A strong password is generated and applied on the mail server, then shown once here for you to
1454	          copy into your other mail apps.
1455	        </p>
1456	      )}
1457	
1458	      {err && <ErrorNote text={err} />}
1459	
1460	      <button className="btn-secondary" onClick={reset} disabled={busy}>
1461	        {busy ? "Resetting…" : password ? "Reset again" : "Reset password"}
1462	      </button>
