243	/** Renders the email body. HTML is dropped into a fully sandboxed iframe (no
244	 *  allow-scripts, no allow-same-origin) so hostile markup/scripts cannot run or
245	 *  reach cookies/storage. Plaintext falls back to a pre block. */
246	function MessageBody({ html, text }: { html: string | null; text: string | null }) {
247	  const ref = useRef<HTMLIFrameElement>(null);
248	  const [height, setHeight] = useState(320);
249	
250	  const doc = html
251	    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
252	        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
253	        body{padding:16px;}
254	        img{max-width:100%;height:auto;}
255	        a{color:#5f2ee8;}
256	        table{max-width:100%;}
257	        pre{white-space:pre-wrap;}
258	        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
259	      </style></head><body>${html}</body></html>`
260	    : null;
261	
262	  // Best-effort autosize: with sandbox="" we cannot read the inner document, so
263	  // grow to a comfortable default and let the iframe scroll for very tall mail.
264	  useEffect(() => {
265	    setHeight(html ? 480 : 0);
266	  }, [html]);
267	
268	  if (doc) {
269	    return (
270	      <iframe
271	        ref={ref}
272	        sandbox=""
273	        srcDoc={doc}
274	        title="Message content"
275	        className="w-full rounded-xl border border-white/[0.06] bg-white"
276	        style={{ height }}
277	      />
278	    );
279	  }
280	
281	  if (text && text.trim()) {
282	    return (
283	      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
284	        {text}
285	      </pre>
286	    );
287	  }
288	
289	  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
290	}
