57	/** Scrolling time grid. `days` has length 1 (Day view) or 7 (Week view). */
58	export function WeekView({
59	  days,
60	  events,
61	  colorFor,
62	  onCreateAt,
63	  onOpenEvent,
64	  onPickDay,
65	}: {
66	  days: Date[];
67	  events: CalEvent[];
68	  colorFor: (calendarId: string) => string;
69	  onCreateAt: (day: Date, hour: number) => void;
70	  onOpenEvent: (ev: CalEvent) => void;
71	  onPickDay: (day: Date) => void;
72	}) {
73	  const scrollRef = useRef<HTMLDivElement>(null);
74	  const hours = useMemo(() => Array.from({ length: 24 }, (_, i) => i), []);
75	
76	  // Scroll to ~8am on mount / view change so the workday is visible.
77	  useEffect(() => {
78	    if (scrollRef.current) scrollRef.current.scrollTop = 7.5 * HOUR_PX;
79	  }, [days.length, days[0]?.toDateString()]);
80	
81	  const now = new Date();
82	  const nowMin = now.getHours() * 60 + now.getMinutes();
83	
84	  const anyAllDay = events.some((e) => e.allDay && days.some((d) => eventOnDay(e.start, e.end, d)));
85	
86	  return (
87	    <div className="flex h-full flex-col">
88	      {/* Day header row */}
89	      <div className="flex flex-none border-b border-white/[0.06] pr-[10px]">
90	        <div className="w-14 flex-none" />
91	        {days.map((day) => {
92	          const today = isToday(day);
93	          return (
94	            <button
95	              key={day.toISOString()}
96	              onClick={() => onPickDay(day)}
97	              className="flex flex-1 flex-col items-center gap-0.5 py-2 transition-colors hover:bg-white/[0.02]"
98	            >
99	              <span className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
100	                {WEEKDAYS_SHORT[day.getDay()]}
101	              </span>
102	              <span
103	                className={`flex h-7 min-w-7 items-center justify-center rounded-full px-1 text-sm font-semibold ${
104	                  today ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-200"
105	                }`}
106	              >
107	                {day.getDate()}
108	              </span>
109	            </button>
110	          );
111	        })}
112	      </div>
113	
114	      {/* All-day strip */}
115	      {anyAllDay && (
116	        <div className="flex flex-none border-b border-white/[0.06] pr-[10px]">
117	          <div className="flex w-14 flex-none items-center justify-end pr-2 text-[10px] font-medium uppercase text-slate-600">
118	            all-day
119	          </div>
120	          {days.map((day) => {
121	            const allDay = events.filter((e) => e.allDay && eventOnDay(e.start, e.end, day));
122	            return (
123	              <div key={day.toISOString()} className="min-w-0 flex-1 space-y-0.5 border-l border-white/[0.05] p-1">
124	                {allDay.map((ev) => {
125	                  const color = colorFor(ev.calendarId);
126	                  return (
127	                    <button
128	                      key={ev.id}
129	                      onClick={() => onOpenEvent(ev)}
130	                      title={ev.title}
131	                      className="block w-full truncate rounded-md px-1.5 py-0.5 text-left text-[11px] font-medium text-white transition-colors hover:brightness-110"
132	                      style={{ backgroundColor: hexToRgba(color, 0.9) }}
133	                    >
134	                      {ev.title || "(untitled)"}
135	                    </button>
136	                  );
137	                })}
138	              </div>
139	            );
140	          })}
141	        </div>
142	      )}
143	
144	      {/* Scrolling time grid */}
145	      <div ref={scrollRef} className="min-h-0 flex-1 overflow-y-auto">
146	        <div className="flex" style={{ height: 24 * HOUR_PX }}>
147	          {/* Hour gutter */}
148	          <div className="w-14 flex-none">
149	            {hours.map((h) => (
150	              <div key={h} className="relative" style={{ height: HOUR_PX }}>
151	                <span className="absolute -top-2 right-2 text-[10px] font-medium tabular-nums text-slate-600">
152	                  {h === 0 ? "" : h < 12 ? `${h} AM` : h === 12 ? "12 PM" : `${h - 12} PM`}
153	                </span>
154	              </div>
155	            ))}
156	          </div>
157	
158	          {/* Day columns */}
159	          {days.map((day) => {
160	            const positioned = layoutDay(events, day);
161	            const today = isToday(day);
162	            return (
163	              <div key={day.toISOString()} className="relative min-w-0 flex-1 border-l border-white/[0.05]">
164	                {/* Hour lines + click targets */}
165	                {hours.map((h) => (
166	                  <div
167	                    key={h}
168	                    onClick={() => onCreateAt(day, h)}
169	                    className="border-b border-white/[0.04] transition-colors hover:bg-white/[0.02]"
170	                    style={{ height: HOUR_PX }}
171	                  />
172	                ))}
173	
174	                {/* Current-time indicator */}
175	                {today && (
176	                  <div
177	                    className="pointer-events-none absolute inset-x-0 z-20 flex items-center"
178	                    style={{ top: (nowMin / 60) * HOUR_PX }}
179	                  >
180	                    <span className="-ml-1 h-2 w-2 flex-none rounded-full bg-red-400" />
181	                    <span className="h-px flex-1 bg-red-400/70" />
182	                  </div>
183	                )}
184	
185	                {/* Events */}
186	                {positioned.map(({ ev, top, height, lane, lanes }) => {
187	                  const color = colorFor(ev.calendarId);
188	                  const widthPct = 100 / lanes;
189	                  const short = height < 34;
190	                  return (
191	                    <button
192	                      key={ev.id}
193	                      onClick={(e) => {
194	                        e.stopPropagation();
195	                        onOpenEvent(ev);
196	                      }}
197	                      title={ev.title}
198	                      className="absolute z-10 overflow-hidden rounded-lg border-l-2 px-1.5 py-1 text-left leading-tight backdrop-blur-sm transition-all hover:z-30 hover:brightness-125"
199	                      style={{
200	                        top,
201	                        height,
202	                        left: `calc(${lane * widthPct}% + 2px)`,
203	                        width: `calc(${widthPct}% - 4px)`,
204	                        backgroundColor: hexToRgba(color, 0.2),
205	                        borderLeftColor: color,
206	                      }}
207	                    >
208	                      <div className={`truncate text-[11px] font-semibold text-slate-100 ${short ? "leading-none" : ""}`}>
209	                        {ev.title || "(untitled)"}
210	                      </div>
211	                      {!short && (
212	                        <div className="truncate text-[10px] tabular-nums text-slate-400">
213	                          {fmtTime(new Date(ev.start))} – {fmtTime(new Date(ev.end))}
214	                        </div>
215	                      )}
216	                    </button>
217	                  );
218	                })}
219	              </div>
220	            );
221	          })}
222	        </div>
223	      </div>
224	    </div>
225	  );
226	}
