3	/* -------------------------------------------------------------------------- */
4	/* Date helpers — all local-time, week starts Sunday                           */
5	/* -------------------------------------------------------------------------- */
6	
7	export const MS_DAY = 86_400_000;
8	
9	export function startOfDay(d: Date): Date {
10	  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
11	}
12	export function endOfDay(d: Date): Date {
13	  return new Date(d.getFullYear(), d.getMonth(), d.getDate(), 23, 59, 59, 999);
14	}
15	export function addDays(d: Date, n: number): Date {
16	  const x = new Date(d);
17	  x.setDate(x.getDate() + n);
18	  return x;
19	}
20	export function addMonths(d: Date, n: number): Date {
21	  const x = new Date(d);
22	  x.setMonth(x.getMonth() + n);
23	  return x;
24	}
25	export function startOfWeek(d: Date): Date {
26	  const x = startOfDay(d);
27	  return addDays(x, -x.getDay());
28	}
29	export function startOfMonth(d: Date): Date {
30	  return new Date(d.getFullYear(), d.getMonth(), 1);
31	}
32	export function endOfMonth(d: Date): Date {
33	  return new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999);
34	}
35	export function isSameDay(a: Date, b: Date): boolean {
36	  return (
37	    a.getFullYear() === b.getFullYear() &&
38	    a.getMonth() === b.getMonth() &&
39	    a.getDate() === b.getDate()
40	  );
41	}
42	export function isSameMonth(a: Date, b: Date): boolean {
43	  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
44	}
45	export function isToday(d: Date): boolean {
46	  return isSameDay(d, new Date());
47	}
48	
49	/** The 6x7 grid of days covering the month that cursor falls in. */
50	export function monthGrid(cursor: Date): Date[] {
51	  const first = startOfWeek(startOfMonth(cursor));
52	  return Array.from({ length: 42 }, (_, i) => addDays(first, i));
53	}
54	
55	/** The 7 days of the week that cursor falls in. */
56	export function weekDays(cursor: Date): Date[] {
57	  const first = startOfWeek(cursor);
58	  return Array.from({ length: 7 }, (_, i) => addDays(first, i));
59	}
60	
61	export const WEEKDAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
62	export const WEEKDAYS_NARROW = ["S", "M", "T", "W", "T", "F", "S"];
63	export const MONTHS = [
64	  "January", "February", "March", "April", "May", "June",
65	  "July", "August", "September", "October", "November", "December",
66	];
67	
68	/** Header title for the current view + cursor. */
69	export function rangeTitle(view: "month" | "week" | "day", cursor: Date): string {
70	  if (view === "month") return `${MONTHS[cursor.getMonth()]} ${cursor.getFullYear()}`;
71	  if (view === "day") {
72	    return cursor.toLocaleDateString([], { weekday: "long", month: "long", day: "numeric", year: "numeric" });
73	  }
74	  const days = weekDays(cursor);
75	  const a = days[0];
76	  const b = days[6];
77	  const sameMonth = a.getMonth() === b.getMonth();
78	  const sameYear = a.getFullYear() === b.getFullYear();
79	  if (sameMonth) return `${MONTHS[a.getMonth()]} ${a.getDate()} – ${b.getDate()}, ${a.getFullYear()}`;
80	  if (sameYear) return `${MONTHS[a.getMonth()].slice(0, 3)} ${a.getDate()} – ${MONTHS[b.getMonth()].slice(0, 3)} ${b.getDate()}, ${a.getFullYear()}`;
81	  return `${MONTHS[a.getMonth()].slice(0, 3)} ${a.getDate()}, ${a.getFullYear()} – ${MONTHS[b.getMonth()].slice(0, 3)} ${b.getDate()}, ${b.getFullYear()}`;
82	}
83	
84	/** Compact time like "9:30 AM" / "2 PM". */
85	export function fmtTime(d: Date): string {
86	  return d
87	    .toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })
88	    .replace(":00", "");
89	}
90	
91	/** "Mon, Jul 27" — for task due dates. */
92	export function fmtDueDate(iso: string): string {
93	  const d = new Date(iso);
94	  if (Number.isNaN(d.getTime())) return "";
95	  const now = new Date();
96	  if (isSameDay(d, now)) return "Today";
97	  if (isSameDay(d, addDays(now, 1))) return "Tomorrow";
98	  if (isSameDay(d, addDays(now, -1))) return "Yesterday";
99	  const sameYear = d.getFullYear() === now.getFullYear();
100	  return d.toLocaleDateString([], sameYear ? { weekday: "short", month: "short", day: "numeric" } : { month: "short", day: "numeric", year: "numeric" });
101	}
102	
103	/** Is the task overdue (due date strictly before the start of today)? */
104	export function isOverdue(iso?: string): boolean {
105	  if (!iso) return false;
106	  const d = new Date(iso);
107	  return !Number.isNaN(d.getTime()) && d.getTime() < startOfDay(new Date()).getTime();
108	}
