110	/* ---- datetime-local <-> ISO ---------------------------------------------- */
111	
112	/** ISO string -> value for <input type="datetime-local"> (local wall time). */
113	export function isoToLocalInput(iso: string): string {
114	  const d = new Date(iso);
115	  if (Number.isNaN(d.getTime())) return "";
116	  const pad = (n: number) => String(n).padStart(2, "0");
117	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
118	}
119	/** ISO -> value for <input type="date">. */
120	export function isoToDateInput(iso: string): string {
121	  const d = new Date(iso);
122	  if (Number.isNaN(d.getTime())) return "";
123	  const pad = (n: number) => String(n).padStart(2, "0");
124	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
125	}
126	/** datetime-local / date input value -> ISO string. */
127	export function localInputToIso(v: string): string {
128	  if (!v) return "";
129	  const d = new Date(v);
130	  return Number.isNaN(d.getTime()) ? "" : d.toISOString();
131	}
