137	/** On-brand fallback palette for calendars without an explicit colour. */
138	export const CAL_PALETTE = [
139	  "#6f47f5", // brand-500
140	  "#3b82f6", // accent-blue
141	  "#22d3ee", // accent-cyan
142	  "#a855f7", // violet
143	  "#ec4899", // pink
144	  "#10b981", // emerald
145	  "#f59e0b", // amber
146	  "#f43f5e", // rose
