149	export function calColor(cal: CalendarInfo | undefined, index = 0): string {
150	  const c = cal?.color?.trim();
151	  if (c && /^#?[0-9a-fA-F]{3,8}$/.test(c)) return c.startsWith("#") ? c : `#${c}`;
152	  return CAL_PALETTE[index % CAL_PALETTE.length];
153	}
