155	/** hex (#rgb / #rrggbb) -> rgba() string. */
156	export function hexToRgba(hex: string, alpha: number): string {
157	  let h = hex.replace("#", "");
158	  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
159	  const int = parseInt(h.slice(0, 6), 16);
160	  if (Number.isNaN(int)) return `rgba(111,71,245,${alpha})`;
161	  const r = (int >> 16) & 255;
162	  const g = (int >> 8) & 255;
163	  const b = int & 255;
164	  return `rgba(${r},${g},${b},${alpha})`;
165	}
